// 코드 스플리팅: 모달은 열 때만 로드
const Modal = React.lazy(() => import('./Modal'));

function Page() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button onClick={() => setOpen(true)}>열기</button>
      {open && (
        <Suspense fallback={<Spinner />}>
          <Modal />
        </Suspense>
      )}
    </>
  );
}

